function batchItem(r:Dw,target=r.desired):BatchItem {const ended=r.stopped||r.receiptStatus==="已完成";const unknown=r.eligibility==="待查询"||r.eligibility==="查询异常";const customer=!ended&&(r.settingIssue||r.eligibility==="卖家管理");const status=ended?"已结束":customer?"等待客户修改":r.missing?"等待前置":unknown?"等待资格查询":r.status==="已验证"?"已验证成功":r.status==="BLOCKED"?"人工BLOCK监控":"待执行";return {id:r.id,waybill:r.waybill,bol:r.bol,fc:r.fc,target,version:r.version||1,stage:customer?"计划已保存，未提交":"DW处理",status,error:ended?"自动处理已结束":r.settingIssue?"货件设置异常：仅保存通知计划":r.eligibility==="卖家管理"?"卖家管理：通知客户修改":r.missing||"—",retry:customer?"供客户通知使用，不显示系统待提交":r.next,canRetry:canRetryDw(r)};}

