  const register=()=>{const row:Reroute={id:`FC-261005-${String(rows.length+42).padStart(4,"0")}`,fba:"FBA1N7Q4R8KM",waybill:"FD2609250048",oldFc:"ONT8",newFc:"SBD1",source:"SMART_REROUTE",notice:"海外仓登记",changedAt:"刚刚",upsert:"待执行",dw:"等待Upsert",reason:"海外仓通知仓点已变更"};setRows(xs=>[row,...xs]);setCreate(false);toast.success("仓点变更已登记",{description:"已创建 UpsertTransportationInfo 任务，成功后自动重算DW"})};
