function ChannelPage() {
  const [transitMin,setTransitMin]=React.useState("12");const [transitMax,setTransitMax]=React.useState("15");const [fist,setFist]=React.useState(true);const [dw,setDw]=React.useState(true);const [configs,setConfigs]=React.useState([["卡派","ONT8","19","6"],["卡派","LAX9","17","5"],["卡派","SMF3","21","7"],["快递派","9*","16","4"]]);const [saved,setSaved]=React.useState(configs);
  return <div className="page"><Title title="服务渠道" copy="美森360 · Amazon FIST 与 DW 配置"><Button variant="outline" onClick={()=>setConfigs(saved)}>取消</Button><Button className="primary" onClick={()=>{if(!transitMin||!transitMax||!Number.isFinite(Number(transitMin))||!Number.isFinite(Number(transitMax))||Number(transitMin)<=0||Number(transitMax)>75||Number(transitMax)<=Number(transitMin)||Number(transitMax)-Number(transitMin)>20)return toast.error("运输最小天数须大于0，最大天数须大于最小天数且不超过75，两者差值不超过20");if(configs.some(x=>!x[1]||!x[2]||!x[3]||Number(x[2])<0||Number(x[3])<0))return toast.error("请填写仓点及有效时效天数");setSaved(configs.map(x=>[...x]));toast.success("演示配置已保存")}}>保存配置</Button></Title><section className="panel channel"><div className="section-title"><strong>基本信息</strong><small>SC-US-MATSON-360</small></div><div className="form four">{[["渠道名称","美森360"],["运输方式","海运"],["起运国","中国"],["目的国","美国"],["关联航线","CLX"],["尾程派送","卡派 / 快递派"],["包税方式","包税 / 不包税"],["服务类型","散货 / 整柜"]].map(([a,b])=><Field key={a} label={a}><Input value={b} readOnly/></Field>)}</div><div className="integrations"><div><i><Link2/></i><span><strong>FIST 对接</strong><small>单号映射、运输信息和 ShipTrack</small></span><Switch checked={fist} onCheckedChange={v=>{setFist(v);if(!v)setDw(false)}}/></div><div className={!fist?"disabled":""}><i><CalendarRange/></i><span><strong>Delivery Window</strong><small>依赖 FIST，向 Amazon 管理 DW</small></span><Switch checked={dw} disabled={!fist} onCheckedChange={setDw}/></div></div><Tabs defaultValue="transit"><TabsList variant="line" className="tabs-line"><TabsTrigger value="transit">预估运输时效</TabsTrigger><TabsTrigger value="warehouse">送仓预估时效</TabsTrigger><TabsTrigger value="claim">理赔承诺时效</TabsTrigger></TabsList><TabsContent value="transit"><div className="form three tab-form"><Field label="亚马逊服务等级"><Select defaultValue="STANDARD"><SelectTrigger><SelectValue/></SelectTrigger><SelectContent><SelectItem value="STANDARD">标准 · STANDARD</SelectItem><SelectItem value="FAST">快速 · FAST</SelectItem><SelectItem value="EXPEDITED">加急 · EXPEDITED</SelectItem></SelectContent></Select></Field><Field label="运输最小天数"><Input type="number" value={transitMin} onChange={e=>setTransitMin(e.target.value)}/></Field><Field label="运输最大天数"><Input type="number" value={transitMax} onChange={e=>setTransitMax(e.target.value)}/></Field></div></TabsContent><TabsContent value="warehouse"><div className="warehouse-head"><span><strong>VD/X4 送仓预估配置</strong><small>按服务渠道 + 尾程方式 + Amazon 仓库匹配</small></span><Button size="sm" className="primary" onClick={()=>setConfigs(xs=>[...xs,["卡派","","0","0"]])}><Plus/>新增配置</Button></div><div className="table-wrap"><Table><TableHeader><TableRow><TableHead>尾程方式</TableHead><TableHead>Amazon 仓库</TableHead><TableHead>VD 后预计送仓天数</TableHead><TableHead>X4 后预计送仓天数</TableHead><TableHead>状态</TableHead><TableHead>操作</TableHead></TableRow></TableHeader><TableBody>{configs.map((x,i)=><TableRow key={i}><TableCell>{x[0]}</TableCell>{[1,2,3].map(j=><TableCell key={j}><Input type={j===1?"text":"number"} value={x[j]} onChange={e=>setConfigs(xs=>xs.map((r,k)=>k===i?r.map((v,c)=>c===j?e.target.value:v):r))}/></TableCell>)}<TableCell><span className="pill ok">启用</span></TableCell><TableCell><div className="actions"><button onClick={()=>setConfigs(xs=>[...xs,[...x]])}>复制</button><button onClick={()=>setConfigs(xs=>xs.filter((_,k)=>k!==i))}>删除</button></div></TableCell></TableRow>)}</TableBody></Table></div><div className="warning compensation-rule"><CircleAlert/><span><strong>缺配置自动补偿</strong><small>当前周不计；按首次补偿计算当地日期，VD第4周、X4第2周。重试不重新计周。仅查询键完整且配置零条命中时触发。</small></span></div></TabsContent><TabsContent value="claim"><div className="empty"><FileText/><strong>沿用现有理赔承诺配置</strong></div></TabsContent></Tabs></section></div>;
}

type WebMcpContext = {
  registerTool: (
    tool: {
      name: string;
      title: string;
      description: string;
      inputSchema: Record<string, unknown>;
      annotations: { readOnlyHint: boolean; untrustedContentHint: boolean };
      execute: (input: unknown) => unknown;
    },
    options?: { signal?: AbortSignal },
  ) => void | Promise<void>;
};

export default function Home() {
  React.useEffect(()=>bind(),[]);
  const [page,setPage]=React.useState<Page>(() => { const value = (window as Window & { amazonInitialView?: string }).amazonInitialView || new URLSearchParams(window.location.search).get("view"); return ["dw","bols","tasks","smart","channel"].includes(value || "") ? value as Page : "dw"; }); const [rows,setRows]=React.useState(windows); const [batches,setBatches]=React.useState(batchesSeed); const [tasks,setTasks]=React.useState(tasksSeed); const [fcChangeGroups,setFcChangeGroups]=React.useState<Array<{bol:string;fc:string}>>([]);
  const [manual,setManual]=React.useState(false); const [manualTarget,setManualTarget]=React.useState<Dw|null>(null); const [manualGroups,setManualGroups]=React.useState<Array<{bol:string;fc:string}>>([]); const [manualSelection,setManualSelection]=React.useState<string[]>([]); const [detail,setDetail]=React.useState(false); const [selected,setSelected]=React.useState<Dw|null>(null); const [taskOpen,setTaskOpen]=React.useState(false); const [task,setTask]=React.useState<Task|null>(null);
  React.useEffect(()=>rememberDemoFailures(tasks,rows),[tasks,rows]);
  const embedded = (window as Window & { amazonEmbedded?: boolean }).amazonEmbedded === true || new URLSearchParams(window.location.search).get("embedded") === "1";
  React.useEffect(() => {
    const listener = (event: MessageEvent) => { if (event.source === window.parent && (event.origin === window.location.origin || (embedded && event.origin === "null")) && event.data?.type === "amazon:navigate" && ["dw","bols","tasks","smart"].includes(event.data.view)) setPage(event.data.view); };
    window.addEventListener("message", listener); if (embedded) { window.dispatchEvent(new Event("amazon:ready")); window.parent.postMessage({type:"amazon:ready"}, "*"); } return () => window.removeEventListener("message", listener);
  }, []);
  React.useEffect(() => { if (embedded) window.parent.postMessage({type:"amazon:page",view:page}, "*"); }, [page, embedded]);
  const nav=(p:Page)=>{setPage(p);window.scrollTo({top:0,behavior:"smooth"})}; const openManual=(r?:Dw)=>{setManualGroups([]);setManualSelection([]);setManualTarget(r||null);setManual(true)}; const openManualMany=(items:Dw[])=>{setManualGroups([]);setManualTarget(null);setManualSelection(items.map(x=>x.id));setManual(true)}; const openBolManual=(groups:Array<{bol:string;fc:string}>)=>{setManualTarget(null);setManualSelection([]);setManualGroups(groups);setManual(true)};
  const showDetail=(r:Dw)=>{setSelected(r);setDetail(true)};
  const retryRows=(ids:string[])=>{const valid=rows.filter(r=>ids.includes(r.id)&&canRetryDw(r));if(!valid.length)return toast.warning("当前没有符合条件的重试任务");const stamp=localStamp();const newTasks:Task[]=valid.map((r,i)=>({id:`RETRY-${Date.now()}-${i}`,fba:r.id,api:"GetDeliveryWindowOptions",trigger:"人工重试当前目标",status:"执行中",tries:1,error:"—",next:"沿用最近资格，不新增资格查询"}));setTasks(xs=>[...newTasks,...xs]);setRows(xs=>xs.map(r=>valid.some(x=>x.id===r.id)?{...r,status:"待同步",next:"同版本重试已排队",history:[...r.history||[],stamp+" · 重试当前版本"]}:r));setBatches(bs=>bs.map(b=>({...b,items:b.items?.map(i=>valid.some(r=>r.id===i.id&&(r.version||1)===i.version)?{...i,status:"待执行",retry:"同版本重试已排队",canRetry:false}:i)})));toast.success(`已排队 ${valid.length} 票有效重试`);};
  const saveManual=(ids:string[],start:string,end:string,_locked:boolean,source:"按FBA货件号"|"按提单号+仓库")=>{
    const chosen=rows.filter(r=>ids.includes(r.id)&&r.receiptStatus!=="已完成"&&!r.stopped);
    if(!chosen.length)return toast.warning("没有可登记货件");
    if(chosen.some(r=>!localDate(r.fc)||end<localDate(r.fc))||end<start||new Date(start+"T12:00:00Z").getUTCDay()!==0||new Date(end+"T12:00:00Z").getUTCDay()!==6||(+new Date(end)-+new Date(start))/86400000!==6){toast.error("请登记完整周日～周六窗口；目的仓日期不满足的货件："+(chosen.filter(r=>!localDate(r.fc)||end<localDate(r.fc)).map(r=>r.id).join("、")||"所选货件"));return;}
    const target=start+" ～ "+end,stamp=localStamp(),batchId="DWB-"+Date.now();
    const updated=chosen.map(x=>{const held=x.settingIssue||!x.allow||!x.shouldProvide||x.missing;const result=x.settingIssue||x.eligibility==="卖家管理"?"计划已保存，等待客户修改":x.missing?"等待前置":held?"等待资格查询":"待执行";return {...x,desired:target,source:"人工登记",version:(x.version||1)+1,savedToday:true,status:(held?x.status:"待同步") as DwStatus,next:held?"计划已保存 · "+result:"已排队 · 沿用最近资格",updated:stamp,updates:[...x.updates||[],{time:stamp,source:"人工登记",before:x.desired,target,actual:x.actual,operator:"Admin",result,task:batchId}]};});
    setRows(xs=>xs.map(x=>updated.find(r=>r.id===x.id)||x));
    setTasks(xs=>xs.map(t=>chosen.some(r=>r.id===t.fba)&&["等待重试","执行中"].includes(t.status)&&/DW|Window/.test(t.api)?{...t,status:"已跳过",next:"旧目标被替换"}:t));
    updated.filter(x=>x.settingIssue||!x.allow).forEach(x=>window.dispatchEvent(new CustomEvent("dw-followup",{detail:{row:x,reason:x.settingIssue?"货件设置异常":"卖家未授权"}})));
    const items=updated.map(r=>batchItem(r,target)),customer=items.filter(i=>i.status==="等待客户修改").length,waiting=items.filter(i=>["等待前置","等待资格查询"].includes(i.status)).length;
    setBatches(xs=>[{id:batchId,source,created:stamp,operator:"Admin",total:items.length,success:0,retrying:0,failed:0,ineligible:waiting,waitingCustomer:customer,kind:"人工DW登记",createdDate:localDate(chosen[0].fc),target,status:items.every(i=>i.status==="等待客户修改")?"已完成":"处理中",items},...xs]);setManual(false);toast.success(`已保存${items.length}票DW计划`);
  };
  const saveFcChange=(ids:string[],newFc:string,source:string)=>{const chosen=rows.filter(r=>ids.includes(r.id)&&r.fc!==newFc&&r.receiptStatus!=="已完成");if(!chosen.length)return toast.warning("没有发生仓点变化的货件");const stamp=localStamp();const created:Task[]=chosen.map((r,i)=>({id:`AMZ-UP-${Date.now()}-${i}`,fba:r.id,api:"UpsertTransportationInfo",trigger:`仓点变更 · ${source}`,status:"执行中",tries:0,error:"—",next:"运输同步后，已人工登记等运营再次登记"}));const batchId="FCB-"+Date.now();created.forEach(t=>{t.batchId=batchId;t.createdDate=localDate(chosen[0].fc)});const items:BatchItem[]=chosen.map(r=>({id:r.id,waybill:r.waybill,bol:r.bol,fc:r.fc,target:r.fc+" → "+newFc,version:r.version||1,stage:"仓点已保存，运输同步待执行",status:"待执行",error:"—",retry:"等待Upsert结果",canRetry:false}));setBatches(bs=>[{id:batchId,source:"按提单号+仓库",created:stamp,createdDate:localDate(chosen[0].fc),kind:"仓点变更",operator:"Admin",total:items.length,success:0,retrying:0,failed:0,ineligible:0,waitingCustomer:0,target:"新仓点 "+newFc,status:"处理中",items},...bs]);setTasks(xs=>[...created,...xs]);setRows(xs=>xs.map(x=>chosen.some(r=>r.id===x.id)?{...x,originalFc:x.fc,fc:newFc,upsertStatus:"执行中",next:x.stopped?"窗口过期，不可恢复；运输信息同步中":x.settingIssue?"设置异常，不可恢复；运输信息同步中":"运输信息同步中 · 等待运营再次人工登记",businessUpdates:[...x.businessUpdates||[],{time:stamp,object:"Amazon仓点",before:x.fc,after:newFc,source,action:"Upsert待执行；已有人工DW不重新预估，等待运营再次登记",task:created.find(t=>t.fba===x.id)!.id}]}:x));setFcChangeGroups([]);toast.success(`已登记 ${chosen.length} 票仓点变化，货件及提单汇总已联动`)};
  React.useEffect(()=>{
    const context=(document as Document & {modelContext?:WebMcpContext}).modelContext;
    if(!context?.registerTool)return;
    const lifecycle=new AbortController();
    const register=(tool:Parameters<WebMcpContext["registerTool"]>[0])=>{void Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>undefined)};
    register({name:"navigate_amazon_workspace",title:"切换 Amazon 管理页面",description:"打开 DW货件列表、DW提单列表、Amazon任务中心、Smart Reroute或服务渠道配置。",inputSchema:{type:"object",properties:{view:{type:"string",enum:["dw","bols","tasks","smart","channel"]}},required:["view"],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){const view=(input as {view?:string})?.view;if(!["dw","bols","tasks","smart","channel"].includes(view||""))throw new Error("无效页面");setPage(view as Page);return{view,opened:true}}});
    register({name:"start_manual_dw_registration",title:"开始人工登记 DW",description:"按 FBA 货件号打开人工登记 Delivery Window 弹窗。",inputSchema:{type:"object",properties:{fbaShipmentId:{type:"string"}},required:["fbaShipmentId"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const id=(input as {fbaShipmentId?:string})?.fbaShipmentId;const row=rows.find(x=>x.id===id);if(!row)throw new Error("未找到 FBA 货件");setPage("dw");setManualTarget(row);setManual(true);return{fbaShipmentId:id,dialog:"opened"}}});
    register({name:"retry_dw_sync",title:"重试 DW 同步",description:"按 FBA 货件号创建一条新的完整 DW 同步重试任务。",inputSchema:{type:"object",properties:{fbaShipmentId:{type:"string"}},required:["fbaShipmentId"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const id=(input as {fbaShipmentId?:string})?.fbaShipmentId;const row=rows.find(x=>x.id===id);if(!row||!canRetryDw(row))throw new Error("当前货件不满足重试条件");retryRows([row.id]);setPage("dw");return{fbaShipmentId:id,status:"待同步"}}});
    return()=>lifecycle.abort();
  },[rows]);
  return <SidebarProvider style={{"--sidebar-width":"240px"} as React.CSSProperties}>{!embedded && <Nav page={page} setPage={nav}/>}<SidebarInset className="shell">{!embedded && <Header page={page} setPage={nav}/>}<main>{page==="dw"&&<DwPage onRetry={retryRows} rows={rows} setRows={setRows} onManual={openManual} onManualMany={openManualMany} onDetail={r=>{setSelected(r);setDetail(true)}}/>}{page==="bols"&&<BolPage rows={rows} onDetail={showDetail} onRegister={openBolManual} onFcChange={setFcChangeGroups}/>} {page==="tasks"&&<TaskPage onRetry={retryRows} onDetail={showDetail} rows={rows} tasks={tasks} setTasks={setTasks} onView={t=>{setTask(t);setTaskOpen(true)}} batches={batches} setBatches={setBatches}/>} {page==="smart"&&<SmartReroutePage/>}{page==="channel"&&<ChannelPage/>}</main></SidebarInset><ManualDialog rows={rows} open={manual} setOpen={setManual} target={manualTarget} groups={manualGroups} selection={manualSelection} onSave={saveManual}/><FcChangeDialog rows={rows} groups={fcChangeGroups} setGroups={setFcChangeGroups} onSubmit={saveFcChange}/><DwSheet tasks={tasks} onTask={t=>{setTask(t);setTaskOpen(true)}} row={rows.find(r=>r.id===selected?.id)||selected} open={detail} setOpen={setDetail} onManual={r=>{setDetail(false);openManual(r)}}/><TaskSheet task={task} open={taskOpen} setOpen={setTaskOpen}/><Toaster richColors closeButton position="top-center"/></SidebarProvider>;
}
